describe('when performing a binary search on an array with one item', function () {
  var a;
  var comparator;
  beforeEach(function () {
    a = [42];
    comparator = function comparator(a, b) {
      return a - b;
    };
  });
  it('for an item that would be before the first item in the array', function () {
    expect(array.binarySearch(a, 41, comparator)).toEqual(null);
  });
  it('for the first item in the array', function () {
    expect(array.binarySearch(a, 42, comparator)).toEqual(42);
  });
  it('for an item that would be after the last item in the array', function () {
    expect(array.binarySearch(a, 43, comparator)).toEqual(null);
  });
});
describe('when performing a binary search on an array with two items', function () {
  var a;
  var comparator;
  beforeEach(function () {
    a = [123, 456];
    comparator = function comparator(a, b) {
      return a - b;
    };
  });
  it('for an item that would be before the first item in the array', function () {
    expect(array.binarySearch(a, 122, comparator)).toEqual(null);
  });
  it('for the first item in the array', function () {
    expect(array.binarySearch(a, 123, comparator)).toEqual(123);
  });
  it('for an item that would be between the first and middle items in the array', function () {
    expect(array.binarySearch(a, 250, comparator)).toEqual(null);
  });
  it('for the last item in the array', function () {
    expect(array.binarySearch(a, 456, comparator)).toEqual(456);
  });
  it('for an item that would be after the last item in the array', function () {
    expect(array.binarySearch(a, 457, comparator)).toEqual(null);
  });
});
